    Renderer BalancePaintProbeRenderer(Fighter f)
    {
        if(f==null||f.body==null)return null;
        return f.body.GetComponentsInChildren<Renderer>(true).FirstOrDefault(r=>r!=null&&(f.weaponPart==null||!r.transform.IsChildOf(f.weaponPart))&&(f.saber==null||!r.transform.IsChildOf(f.saber))&&(f.shield==null||!r.transform.IsChildOf(f.shield))&&(f.thruster==null||!r.transform.IsChildOf(f.thruster))&&(f.jumpFlame==null||!r.transform.IsChildOf(f.jumpFlame))&&r.sharedMaterials.Any(m=>m!=null&&(m.HasProperty("_BaseColor")||m.HasProperty("_Color"))));
    }
